/**
 * The root layout renders <html lang> and the tab title in the language proxy.ts decided
 * (x-locale header), so the first paint is already in that language.
 *
 * Value: protects=French first paint: <html lang="fr"> and the French tab title from x-locale;
 * unsupported or missing values fall back to English; fails_when=the layout stops reading
 * x-locale or trusts an unsupported value; why_new=no test covered app/layout.tsx; seam=none
 * Generated by /ship test coverage audit (pass 1).
 */
import type { ReactElement } from "react";
import { translate } from "@/lib/translate";
import RootLayout, { generateMetadata } from "./layout";

let mockLocaleHeader: string | null = null;
jest.mock("next/headers", () => ({
  headers: async () => new Headers(mockLocaleHeader === null ? {} : { "x-locale": mockLocaleHeader }),
}));
jest.mock("next/font/google", () => ({
  Geist: () => ({ variable: "geist" }),
  Geist_Mono: () => ({ variable: "geist-mono" }),
}));

async function renderedFor(header: string | null) {
  mockLocaleHeader = header;
  const html = (await RootLayout({ children: null })) as ReactElement<{ lang: string }>;
  const metadata = await generateMetadata();
  return { lang: html.props.lang, title: metadata.title, description: metadata.description };
}

describe("RootLayout", () => {
  it("renders the page and its title in the language the proxy decided", async () => {
    expect(await renderedFor("fr")).toEqual({
      lang: "fr",
      title: translate("fr", "meta.title"),
      description: translate("fr", "meta.description"),
    });
  });

  it("falls back to English for a missing or unsupported language", async () => {
    for (const header of [null, "es"]) {
      expect(await renderedFor(header)).toEqual({
        lang: "en",
        title: translate("en", "meta.title"),
        description: translate("en", "meta.description"),
      });
    }
  });
});
